var residentVehicleCatalog = [{ id: 211, name: "\uACE8\uBAA9 \uC8FC\uCC28\uC6A9 \uD574\uCE58\uBC31", category: "\uC8FC\uCC28\xB7\uC774\uB3D9", source: "Quaternius \xB7 CC0 \uC644\uC131\uCC28\uB97C \uB2E8\uC21C\uD654", file: "alley-211.glb" }, { id: 212, name: "\uACE8\uBAA9 \uC8FC\uCC28\uC6A9 \uC18C\uD615 \uC138\uB2E8", category: "\uC8FC\uCC28\xB7\uC774\uB3D9", source: "Quaternius \xB7 CC0 \uC644\uC131\uCC28\uB97C \uB2E8\uC21C\uD654", file: "alley-212.glb" }];
function createResidentVehicle(id) {
  const data = importedCars[id], g = new Group();
  g.name = id === 173 ? "\uACE8\uBAA9 \uC8FC\uCC28\uC6A9 \uC18C\uD615 SUV" : id === 211 ? "\uACE8\uBAA9 \uC8FC\uCC28\uC6A9 \uD574\uCE58\uBC31" : "\uACE8\uBAA9 \uC8FC\uCC28\uC6A9 \uC18C\uD615 \uC138\uB2E8";
  g.userData = { source: "Quaternius Realistic Car Pack, CC0", sourceModel: data.source, triangles: data.triangles };
  const material = (color, kind) => new MeshStandardMaterial({ color, roughness: kind === "glass" ? 0.32 : 0.8 });
  for (const p of data.parts) {
    const geo = new BufferGeometry();
    geo.setAttribute("position", new Float32BufferAttribute(p.positions, 3));
    geo.computeVertexNormals();
    const m = new Mesh(geo, material(p.color, p.name === "Windows" ? "glass" : "car"));
    m.name = "car-" + p.name;
    m.userData.detailKind = p.name === "Windows" ? "glass" : "car";
    g.add(m);
  }
  for (const [i, w] of data.wheels.entries()) {
    const tire = new Mesh(new CylinderGeometry(w.radius, w.radius, w.width, 12), material("#303638", "rubber"));
    tire.rotation.x = Math.PI / 2;
    tire.position.fromArray(w.center);
    tire.name = "tyre-" + i;
    tire.userData = { detailKind: "rubber", groundContactWheel: true };
    g.add(tire);
    const rim = new Mesh(new CylinderGeometry(w.radius * 0.57, w.radius * 0.57, 0.012, 8), material("#949f9f", "metal"));
    rim.rotation.x = Math.PI / 2;
    rim.position.fromArray(w.center);
    rim.position.z += Math.sign(w.center[2]) * (w.width / 2 + 3e-3);
    rim.name = "rim-" + i;
    rim.userData.detailKind = "metal";
    g.add(rim);
    const hub = new Mesh(new CircleGeometry(w.radius * 0.18, 4), material("#505b5e", "metal"));
    hub.material.side = DoubleSide;
    hub.position.copy(rim.position);
    hub.position.z += Math.sign(w.center[2]) * 9e-3;
    hub.name = "hub-" + i;
    hub.userData.detailKind = "metal";
    g.add(hub);
  }
  return g;
}

